                    $(document).ready(function () {
                        var sessionId = $.cookie('BetySessionId_AETPIA');
                        var authId = $.cookie('AuthId_AETPIA');
                        var autoLoginId = $.cookie('netAutoLoginId_AETPIA');
                        var loginUrl = '';
                        var param = {};
                        var loginState = false;

                        if (sessionId !== null && authId !== null) {
                            loginUrl = "//t.pia.jp/pia/event/ajax/Login.do";
                            param = {"betySessionId": sessionId, "piaAutoLoginId": authId};
                        } else if (autoLoginId !== null) {
                            loginUrl = "//t.pia.jp/pia/event/ajax/AutoLogin.do";
                            param = {"netAutoLoginId": autoLoginId};
                        }

                        if (loginUrl !== '') {
                            $.ajax({
                                type: "GET",
                                cache: false,
                                url: loginUrl,
                                data: param,
                                dataType: "json",
                            }).done(function (data) {
                                loginState = data.authSucceeded;
                                var userNm = data.lastNm + ' ' + data.fastNm;
                                var ntMembId = data.ntMembId;
                                var sexTyp = data.sexTyp;
                                var age = data.age;
                                var prefectureCd = data.prefectureCd;

                                if (loginState) {
                                    $('body').removeClass('tg_pia-status-logout').addClass('tg_pia-status-login');
                                    $("#menu-login").remove();
                                    $("#menu-logout").remove();
                                    $("#menu-username").html('<a href="https://ticket-account.pia.jp/pia/mypage.do" class="userStatus__link sl_header_topInner--text" ><span class="userStatus__icon"></span><span class="userStatus__text sl_header--name" id="sp-user-name">' + userNm + '</span><span class="userStatus__textAfter" id="sp-user-name-after">さん</span></a>');
                                    $('#authed_flg').val('true');
                                    $('#nt_memb_id').val(ntMembId);
                                    $('#sexTyp').val(sexTyp);

